# runs when you pip install
# generated by ChatGPT


from setuptools import setup, find_packages
from setuptools.command.develop import develop
from setuptools.command.install import install

import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path


PROJECT_DIR = Path(__file__).resolve().parent

# Check Python version
if sys.version_info < (3, 10):
    raise RuntimeError("Python 3.10 or newer is required.")

# Avoid accidentally importing a vendored version of lie_learn.
if (PROJECT_DIR / "lie_learn").is_dir():
    raise RuntimeError(
        "A top-level lie_learn/ directory exists. "
        "Rename or remove it before installing."
    )


class InstallLieLearnMixin:
    """Install lie_learn and its required precomputed matrices."""

    def install_lie_learn(self):
        print("[setup] Installing lie_learn from GitHub...")

        with tempfile.TemporaryDirectory(
            prefix="sphericalcnn-lie-learn-"
        ) as temp_dir:

            source_dir = Path(temp_dir) / "lie_learn"

            subprocess.check_call([
                "git",
                "clone",
                "--depth", "1",
                "https://github.com/AMLab-Amsterdam/lie_learn.git",
                str(source_dir),
            ])

            print("[setup] Installing lie_learn...")

            subprocess.check_call([
                sys.executable,
                "-m", "pip",
                "install",
                "--no-build-isolation",
                "--no-cache-dir",
                str(source_dir),
            ])

            # Copy required Wigner matrices into installed package.
            source_matrices = (
                source_dir
                / "lie_learn"
                / "representations"
                / "SO3"
                / "pinchon_hoggan"
            )

            import lie_learn

            installed_package = Path(lie_learn.__file__).resolve().parent

            destination = (
                installed_package
                / "representations"
                / "SO3"
                / "pinchon_hoggan"
            )

            destination.mkdir(parents=True, exist_ok=True)

            for filename in (
                "J_dense_0-150.npy",
                "J_block_0-150.npy",
            ):
                source = source_matrices / filename

                if not source.is_file():
                    raise RuntimeError(
                        f"Missing upstream data file: {source}"
                    )

                shutil.copy2(source, destination / filename)
                print(f"[setup] Installed {filename}")


class CustomDevelop(InstallLieLearnMixin, develop):
    def run(self):
        super().run()
        self.install_lie_learn()


class CustomInstall(InstallLieLearnMixin, install):
    def run(self):
        super().run()
        self.install_lie_learn()


setup(
    name="spherical-cnn",
    version="0.1.0",
    description="Spherical Convolutional Neural Network implementation",

    packages=find_packages(
        exclude=("tests", "tests.*", "lie_learn", "lie_learn.*")
    ),

    py_modules=[
        "model",
        "train",
        "gendata",
    ],

    python_requires=">=3.10",

    install_requires=[
        "numpy",
        "scipy",
        "requests",
        "Cython",
        "torch",
        "torchvision",
    ],

    cmdclass={
        "develop": CustomDevelop,
        "install": CustomInstall,
    },

    include_package_data=True,
    zip_safe=False,
)

